"use strict";

// Real payloads from the BillBull receipt and label builders, generated by
// billbull-frontend/src/utils/__tests__/printerPayloadFixtures.test.js and
// shared with the backend's PrinterPayloadFixturesTest. Each must pass its
// own protocol's policy and reach the printer byte for byte when sent to a
// destination set up for that protocol, and must send nothing when sent to a
// destination set up for the other one — whatever route it is sent on.

const fs = require("node:fs");
const path = require("node:path");
const test = require("node:test");
const assert = require("node:assert/strict");
const { inspectEscPos } = require("../lib/escposPolicy");
const { inspectZpl } = require("../lib/zplPolicy");
const { startAgent } = require("./helpers");

const DIR = path.resolve(__dirname, "../../../billbull-backend/src/test/resources/printer-payloads");
const manifest = JSON.parse(fs.readFileSync(path.join(DIR, "manifest.json"), "utf8"));
const POLICY = { escpos: inspectEscPos, zpl: inspectZpl };
const ROUTE = { escpos: "/print/escpos", zpl: "/print/zpl" };
const OTHER = { escpos: "zpl", zpl: "escpos" };

test("the fixture set covers both protocols", () => {
  assert.ok(manifest.filter((m) => m.protocol === "escpos").length >= 5);
  assert.ok(manifest.filter((m) => m.protocol === "zpl").length >= 5);
});

for (const { file, protocol } of manifest) {
  test(`${file}: allowed by the ${protocol} policy`, () => {
    assert.deepEqual(POLICY[protocol](fs.readFileSync(path.join(DIR, file))), { allowed: true });
  });
}

for (const { file } of manifest.filter((m) => m.protocol === "escpos")) {
  // Binary ESC/POS is never a well-formed label. (The reverse is not true — a
  // label is printable text to the ESC/POS walker — which is why the
  // destination, not the walker, keeps labels off receipt printers.)
  test(`${file}: refused by the ZPL policy`, () => {
    assert.equal(inspectZpl(fs.readFileSync(path.join(DIR, file))).allowed, false);
  });
}

test.describe("over HTTP, against configured destinations", () => {
  let agent;
  test.beforeEach(async () => { agent = await startAgent(); });
  test.afterEach(async () => { await agent.close(); });

  const queueFor = { escpos: "POS-80C", zpl: "ZD220" };
  const netFor = (protocol) => ({ connectionType: "NETWORK_IP", ipAddress: "127.0.0.1",
    portNumber: (protocol === "zpl" ? agent.labelPrinter : agent.printer).port });
  const send = (token, route, target, bytes) => agent.request({ method: "POST", path: route, headers: agent.authed(token),
    body: { ...target, dataBase64: bytes.toString("base64") } });

  test("every fixture prints byte for byte to a queue and a network printer set up for its protocol", async () => {
    const token = await agent.pair();
    for (const { file, protocol } of manifest) {
      const bytes = fs.readFileSync(path.join(DIR, file));
      const usb = await send(token, ROUTE[protocol], { printerName: queueFor[protocol], connectionType: "USB" }, bytes);
      assert.equal(usb.status, 200, `${file}: ${usb.text}`);
      const job = agent.queueJobs.pop();
      assert.ok(job.buffer.equals(bytes), file);
      assert.equal(job.printerName, queueFor[protocol]);

      const net = await send(token, ROUTE[protocol], netFor(protocol), bytes);
      assert.equal(net.status, 200, `${file}: ${net.text}`);
    }
    const expected = { escpos: manifest.filter((m) => m.protocol === "escpos"), zpl: manifest.filter((m) => m.protocol === "zpl") };
    const deadline = Date.now() + 3000;
    while ((agent.printer.jobs.length < expected.escpos.length || agent.labelPrinter.jobs.length < expected.zpl.length) && Date.now() < deadline) {
      await new Promise((r) => setTimeout(r, 20));
    }
    assert.deepEqual(agent.printer.jobs.map((b) => b.toString("base64")),
      expected.escpos.map(({ file }) => fs.readFileSync(path.join(DIR, file)).toString("base64")));
    assert.deepEqual(agent.labelPrinter.jobs.map((b) => b.toString("base64")),
      expected.zpl.map(({ file }) => fs.readFileSync(path.join(DIR, file)).toString("base64")));
  });

  test("every fixture sent to a destination of the other protocol sends nothing, on either route", async () => {
    const token = await agent.pair();
    for (const { file, protocol } of manifest) {
      const bytes = fs.readFileSync(path.join(DIR, file));
      const other = OTHER[protocol];
      for (const route of [ROUTE[protocol], ROUTE[other]]) {
        for (const target of [{ printerName: queueFor[other], connectionType: "USB" }, netFor(other)]) {
          const res = await send(token, route, target, bytes);
          // Own route → the destination disagrees. Other route → the route
          // matches the destination, so the destination's own policy decides.
          if (route === ROUTE[protocol]) {
            assert.equal(res.status, 409, `${file} via ${route}: ${res.text}`);
            assert.equal(res.json.code, "AGENT_PROTOCOL_MISMATCH");
          } else if (protocol === "escpos") {
            assert.equal(res.status, 403, `${file} via ${route}: ${res.text}`);
            assert.equal(res.json.code, "AGENT_COMMAND_FORBIDDEN");
            assert.equal(res.json.protocol, "zpl");
          } else {
            // A label on the receipt route to a receipt printer is just text
            // to that printer; it is the destination that matters, and this
            // one is a receipt printer. Record that it is allowed, and drain.
            assert.equal(res.status, 200, `${file} via ${route}: ${res.text}`);
          }
        }
      }
    }
    await agent.settle();
    assert.equal(agent.labelPrinter.jobs.length, 0, "nothing reached the Zebra");
    assert.ok(agent.queueJobs.every((j) => j.printerName === "POS-80C"), "nothing reached the Zebra queue");
  });
});
